const cp = await import("node:child_process");
const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows"};
function ps(cmd, timeout=60000){
  return new Promise(r=>cp.exec(cmd, {shell:"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe", env:ENV, windowsHide:true, maxBuffer: 20*1024*1024, timeout}, (e,so,se)=>r({code:e?e.code:0, so:String(so||""), se:String(se||"")})));
}
const out = await ps(`
$h='C:\\Users\\a7med\\AppData\\Local\\hermes'
Write-Host '=== hermes home top ==='
Get-ChildItem $h | Select-Object Mode,Length,LastWriteTime,Name | Format-Table -AutoSize | Out-String -Width 200
Write-Host '=== logs ==='
Get-ChildItem (Join-Path $h 'logs') -ErrorAction SilentlyContinue | Select-Object Length,LastWriteTime,Name | Format-Table -AutoSize | Out-String -Width 200
Write-Host '=== state ==='
Get-ChildItem (Join-Path $h 'state') -ErrorAction SilentlyContinue | Select-Object Length,LastWriteTime,Name | Format-Table -AutoSize | Out-String -Width 200
Write-Host '=== config files ==='
Get-ChildItem $h -File -Force | Select-Object Length,LastWriteTime,Name | Format-Table -AutoSize | Out-String -Width 200
Write-Host '=== gateway process ==='
Get-CimInstance Win32_Process -Filter "Name='python.exe'" | Select-Object ProcessId,CommandLine | Format-List | Out-String -Width 300
Write-Host '=== heartbeat ==='
Get-Content (Join-Path $h 'state\\gateway.heartbeat') -ErrorAction SilentlyContinue
Write-Host '=== ollama ==='
Get-CimInstance Win32_Process -Filter "Name='ollama.exe'" | Select-Object ProcessId,CommandLine | Format-List | Out-String -Width 300
`);
console.log(out.so); if(out.se) console.log("ERR:", out.se.slice(0,2000));
"}

