const cp = await import("node:child_process");
const ENV = {...process.env, USERPROFILE:"C:\\Users\\a7med", APPDATA:"C:\\Users\\a7med\\AppData\\Roaming", LOCALAPPDATA:"C:\\Users\\a7med\\AppData\\Local", HOME:"C:\\Users\\a7med", SYSTEMROOT:"C:\\Windows", OLLAMA_HOST:"http://127.0.0.1:11434"};
const HERMES = "C:\\Program Files\\WindowsApps\\NousResearchInc.HermesAgent_2026.7512.1650.0_x64__sznbd6dv1j3v4\\app\\resources\\agent-payload\\bin\\hermes.exe";
function run(args, timeout=90000){
  return new Promise(function(r){
    const p = cp.spawn(HERMES, args, {env:ENV, windowsHide:true, stdio:["ignore","pipe","pipe"]});
    let so="", se="";
    p.stdout.on("data", d=>so+=d);
    p.stderr.on("data", d=>se+=d);
    const t = setTimeout(()=>{ try{p.kill();}catch(e){} }, timeout);
    p.on("close", c=>{ clearTimeout(t); r({code:c, so, se}); });
    p.on("error", e=>{ clearTimeout(t); r({code:-1, so, se:se+"\nSPAWNERR "+e.message}); });
  });
}
