const { DatabaseSync } = await import("node:sqlite");
const path = "C:\\Users\\a7med\\.openclaw\\state\\openclaw.sqlite";
const db = new DatabaseSync(path, { readOnly: true });
function redact(s){ return String(s).replace(/\d{6,}:[A-Za-z0-9_-]{20,}/g, "<TG_TOKEN>").slice(0,600); }
const candidates = ["plugin_state_entries","secret_store_entries","current_conversation_bindings","channel_ingress_events","plugin_binding_approvals","config_machine_state","user_preferences","projects","agent_provenance","diagnostic_events"];
for (const t of candidates){
  let rows;
  try { rows = db.prepare("SELECT * FROM "+t).all(); } catch(e){ console.log(t, "ERR", e.message); continue; }
  const hit = rows.filter(r => /telegram|whatsapp|whats_app|wa:/i.test(JSON.stringify(r)));
  console.log("== "+t+": rows="+rows.length+" hits="+hit.length);
  for (const h of hit.slice(0,6)) console.log("   ", redact(JSON.stringify(h)));
}
", "description": "Search openclaw sqlite for telegram/whatsapp rows"}

